commits.patch:
diff --git a/lib/parsedate.c b/lib/parsedate.c
index b4dd97b..f598cc7 100644
--- a/lib/parsedate.c
+++ b/lib/parsedate.c
@@ -114,7 +114,8 @@ struct tzinfo {

 #define tDAYZONE (-60)         /* offset for daylight savings time */

-/* alpha-sorted list of single-letter time zones */
+/* alpha-sorted list of single-letter time zones. J is skipped since it is
+   not a timezone, so no slot is wasted on it. */
 static const struct tzinfo tzone[] = {
   { "A", -1 * 60 },            /* Alpha */
   { "B", -2 * 60 },            /* Bravo */
@@ -125,7 +126,6 @@ static const struct tzinfo tzone[] = {
   { "G", -7 * 60 },            /* Golf */
   { "H", -8 * 60 },            /* Hotel */
   { "I", -9 * 60 },            /* India */
-  { "", -1 },          /* not a timezone */
   { "K", -10 * 60 },           /* Kilo */
   { "L", -11 * 60 },           /* Lima */
   { "M", -12 * 60 },           /* Mike */
@@ -335,9 +335,14 @@ UNITTEST int checktz(const char *check, size_t len)
     return -1;
   else if(len == 1) {
     /* short-cut single letter names */
+    int tzidx;
     if((check[0] < 'A') || (check[0] > 'Z') || (check[0] == 'J'))
       return -1; /* no such tz */
-    return tzone[check[0] - 'A'].offset * 60;
+    /* tzone[] has no entry for J, so letters after it shift down by one */
+    tzidx = check[0] - 'A';
+    if(check[0] > 'J')
+      tzidx--;
+    return tzone[tzidx].offset * 60;
   }
   else if(len == 2) {
     /* two-letter names */
